import math

def predict(probe):
    # Beliefs:
    # - There is a central interval roughly [-3, 3] where output ~ 11.8 (mean), noisy [E2,E4,E6,E14,E20]
    # - Outside that interval, output ~ 0 (mean), noisy, range ~[-3,3] [E2,E8,E10,E12,...]
    # - Left boundary between -3.1 and -3.05 [E6,E18,E20]; right boundary ~3.0 [E4,E6]
    # - Outputs are noisy; predict region mean (minimizes expected error)
    xs = probe.get("x", [])
    ys = []
    for x in xs:
        try:
            xv = float(x)
        except Exception:
            ys.append(None)
            continue
        if -3.05 < xv <= 3.0:
            ys.append(11.8)
        else:
            ys.append(0.0)
    return {"y": ys}
